import{_ as t,o as r,c as o,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"CC Switch 接入 Hermes：你的 AI 智能体助手也能用中转站","description":"","frontmatter":{"title":"CC Switch 接入 Hermes：你的 AI 智能体助手也能用中转站","date":"2026-09-18T20:00:00.000Z","tags":["CC Switch","Hermes","中转站","教程"],"categories":["技术折腾"]},"headers":[],"relativePath":"guide/07-hermes.md","filePath":"guide/07-hermes.md"}'),a={name:"guide/07-hermes.md"};function i(l,e,c,n,d,h){return r(),o("div",null,[...e[0]||(e[0]=[s('<blockquote><p>生命不息，折腾不止。</p></blockquote><p>Hermes 是一个开源的 AI 智能体（Agent）框架，可以接管你的服务器、自动化跑任务。这篇教小白：用 CC Switch 把 AI 中转站接进 Hermes，让智能体用上你的中转站模型，一个 Key 管全家。</p><h2 id="一、hermes-是什么" tabindex="-1">一、Hermes 是什么 <a class="header-anchor" href="#一、hermes-是什么" aria-label="Permalink to &quot;一、Hermes 是什么&quot;">​</a></h2><p>Hermes（Hermes Agent）是 Nous Research 出的开源 AI 智能体框架，跑在服务器/电脑上，能接大模型、调用工具、自动完成任务，还能通过 Telegram、飞书、微信这些平台跟你聊天办事。</p><p>它本身支持配置多种模型供应商，但配置在 YAML 文件里——<strong>CC Switch 帮你可视化切换</strong>，点一下就换模型供应商，不用手动改配置。</p><h2 id="二、准备工作" tabindex="-1">二、准备工作 <a class="header-anchor" href="#二、准备工作" aria-label="Permalink to &quot;二、准备工作&quot;">​</a></h2><blockquote></blockquote><ol><li><strong>中转站 API Key</strong>：后台 → API Keys → 创建，复制 <code>sk-</code> Key</li><li><strong>Node.js</strong>：nodejs.org 装 LTS 版（CC Switch 依赖）</li><li><strong>安装 Hermes</strong>：按 Hermes 官方文档安装（有 Docker 和本地两种方式）</li><li><strong>下载 CC Switch</strong>：官网 ccswitch.io 或 GitHub Releases</li></ol><h2 id="三、在-cc-switch-里添加-hermes-供应商" tabindex="-1">三、在 CC Switch 里添加 Hermes 供应商 <a class="header-anchor" href="#三、在-cc-switch-里添加-hermes-供应商" aria-label="Permalink to &quot;三、在 CC Switch 里添加 Hermes 供应商&quot;">​</a></h2><ol><li>打开 CC Switch</li><li>左侧切换器选 <strong>Hermes</strong> 应用</li><li>点右上角 <strong>+</strong></li><li>预设选 <strong>自定义</strong>（Hermes 一般需要手动填）</li><li>填关键信息： <ul><li><strong>名称</strong>：如 <code>我的中转站</code></li><li><strong>API 地址（Base URL）</strong>：<code>https://ai.aklibk.com/v1</code>（中转站文档为准）</li><li><strong>API Key</strong>：粘贴中转站 Key</li><li><strong>模型</strong>：填一个支持的模型名</li></ul></li><li>点 <strong>添加</strong></li></ol><blockquote></blockquote><blockquote><p>不同版本 Hermes 的配置结构可能有差异，添加后先在 CC Switch 里点一下切换，再重启 Hermes 让它重新读取配置。</p></blockquote><h2 id="四、切换并验证" tabindex="-1">四、切换并验证 <a class="header-anchor" href="#四、切换并验证" aria-label="Permalink to &quot;四、切换并验证&quot;">​</a></h2><ol><li>在 Hermes 面板点一下刚添加的供应商（选中）</li><li>重启 Hermes 智能体</li><li>通过它的对话入口（如 Telegram）问一句</li></ol><blockquote></blockquote><p>&quot;你好&quot;——能回复就成功了</p><h2 id="五、常见问题" tabindex="-1">五、常见问题 <a class="header-anchor" href="#五、常见问题" aria-label="Permalink to &quot;五、常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>解决</th></tr></thead><tbody><tr><td>切换后没变化</td><td>重启 Hermes 让它重新读配置</td></tr><tr><td>报 401</td><td>API 地址或 Key 填错</td></tr><tr><td>报模型不存在</td><td>换中转站后台实际提供的模型名</td></tr><tr><td>报 base_url 格式错</td><td>确认中转站要求带不带 <code>/v1</code></td></tr></tbody></table><h2 id="六、总结" tabindex="-1">六、总结 <a class="header-anchor" href="#六、总结" aria-label="Permalink to &quot;六、总结&quot;">​</a></h2><p>Hermes 接中转站：<strong>下载 CC Switch → Hermes 面板添加（填地址+Key）→ 切换 → 重启 Hermes</strong>。</p><p>想让你的 AI 智能体用上全家桶模型、还便宜？试试 Aklibk API 中转站（ai.aklibk.com），国内直连、免绑卡、人民币按量付费。</p><blockquote><p>系列预告：CC Switch 支持的应用还剩 Gemini CLI 没讲，下一篇补上，凑齐全家桶。</p></blockquote>',22)])])}const u=t(a,[["render",i]]);export{g as __pageData,u as default};
